using Intranet.Entity;using System.Text.RegularExpressions;
namespace Intranet.Service;
public interface IPcpAnaliticasService{Task<ServiceResult> Requirements(string np,CancellationToken ct);Task<ServiceResult> Send(PcpSend request,CancellationToken ct);Task<ServiceResult> Read(string? np,long? id,long? cursor,string? status,CancellationToken ct);}
public sealed class PcpAnaliticasService(IPcpAnaliticasRepository repository,IAnalisisRbOperationsRepository operations,GestionIdentity identity,RequestActor actor):ApplicationService(actor),IPcpAnaliticasService {
 public static AnalisisRbSelectedOperation Snapshot(AnalisisRbOperation row)=>new(row.BlockCode,row.BlockName,row.Sequence,row.Code,row.Variant,row.Description,row.StandardTime);
 private static string Key(AnalisisRbSelectedOperation row)=>string.Join("|",row.BlockCode,row.Sequence,row.Code,row.Variant);
 public static PcpSelection Validate(PcpSend request,AnalisisRbOperations current){
 if(request.RequestId==Guid.Empty||request.Tariff!=current.Tariff||request.Variant!=current.SelectedVariant||request.Np!=current.Np||request.Operations is null||request.Selected is null||request.Operations.Count>3000||request.Selected.Count<1||request.Selected.Count>3000||request.Operations.Any(x=>x is null)||request.Selected.Any(x=>x is null))throw new ArgumentException("Revisa la NP y las operaciones antes de enviar.");
 var rows=current.Rows.Where(x=>x.Sector==request.Sector).ToList();var all=rows.Select(Snapshot).ToList();if(all.Count==0||!all.OrderBy(Key).SequenceEqual(request.Operations.OrderBy(Key)))throw new ArgumentException("El tarifado cambió. Vuelve a consultar las operaciones antes de enviar.");
 var selectedKeys=request.Selected.Select(Key).ToHashSet();var selected=all.Where(x=>selectedKeys.Contains(Key(x))).ToList();if(selectedKeys.Count!=request.Selected.Count||!selected.OrderBy(Key).SequenceEqual(request.Selected.OrderBy(Key)))throw new ArgumentException("La selección de procesos no es válida.");
 var total=all.Sum(x=>x.StandardTime);var time=selected.Sum(x=>x.StandardTime);if(time<=0||total<=0||time>total)throw new ArgumentException("Selecciona operaciones con un tiempo mayor que cero.");
 var sector=new AnalisisRbSectorAnalysis(current.Tariff,current.SelectedVariant,request.Sector,rows[0].SectorName,total,all.Count,selected.Count,all.Count==selected.Count);return new(request.Np,sector,selected);
 }
 public async Task<ServiceResult> Send(PcpSend request,CancellationToken ct){var user=identity.GetUser(User);if(!identity.CanRegister(User)||!Actor.WriteRequested)throw new UnauthorizedAccessException();request.Np=(request.Np??"").Trim().ToUpperInvariant();if(!Regex.IsMatch(request.Np,"^[A-Z0-9]{5}$")||!Regex.IsMatch(request.Variant??"","^[A-Z0-9]$")||!Regex.IsMatch(request.Sector??"","^[A-Z0-9]{1,10}$"))throw new ArgumentException("NP, sector o variante inválidos.");var requirements=await repository.Requirements(request.Np,ct);if(requirements.Missing.Count>0)throw new ArgumentException("No se puede enviar a Logística. Falta: "+string.Join("; ",requirements.Missing));var current=await operations.Read(request.Np,request.Variant,ct)??throw new ArgumentException("No se encontró la NP.");return Ok(await repository.Send(request.RequestId,Validate(request,current),user,ct));}
 public async Task<ServiceResult> Requirements(string np,CancellationToken ct){identity.GetUser(User);np=(np??"").Trim().ToUpperInvariant();if(!Regex.IsMatch(np,"^[A-Z0-9]{5}$"))throw new ArgumentException("La NP debe tener 5 caracteres.");return Ok(await repository.Requirements(np,ct));}
 public async Task<ServiceResult> Read(string? np,long? id,long? cursor,string? status,CancellationToken ct){identity.GetUser(User);np=string.IsNullOrWhiteSpace(np)?null:np.Trim().ToUpperInvariant();if(np!=null&&!Regex.IsMatch(np,"^[A-Z0-9]{5}$")||id<=0||cursor<=0||status!=null&&status is not ("E" or "A" or "S"))throw new ArgumentException("Revisa los filtros de envíos PCP.");return Ok(await repository.Read(np,id,cursor,status,ct));}
 public static void ValidateForAnalysis(AnalisisRbSave request,PcpEntry entry){var selection=entry.Selection??throw new ArgumentException("No se pudo leer el envío PCP.");if(entry.Status!="E"&&entry.Status!="A"||entry.Np!=request.Source.Np||request.SectorAnalysis!=selection.SectorAnalysis||request.UsedTime!=entry.SelectedTime)throw new ArgumentException("El análisis no coincide con el envío PCP o fue reemplazado.");if(entry.IsComplete&&request.PartialSelection!=null||!entry.IsComplete&&(request.PartialSelection==null||!request.PartialSelection.Operations.SequenceEqual(selection.Operations)||request.PartialSelection.Tariff!=entry.Tariff||request.PartialSelection.Variant!=entry.Variant||request.PartialSelection.Sector!=entry.Sector||request.PartialSelection.SectorTotalTime!=entry.TotalTime))throw new ArgumentException("Las operaciones recibidas de PCP son de solo lectura.");}
}
